        pair_map[x] = y
        pair_map[y] = x

    # Create a dictionary to store the preference rank of each person
    rank = {}
    for i in range(n):
        rank[i] = {}
        for idx, friend in enumerate(preferences[i]):
            rank[i][friend] = idx

    # Initialize the count of unhappy friends
    unhappy_count = 0

    # Iterate through each person to check if they are unhappy
