        y = pair_map[x]
        # Get the rank of y in x's preferences
        y_rank = rank[x][y]
        # Iterate through x's preferences to find if there is a u that x prefers over y
        for u in preferences[x]:
            if u == y:
                break
            # Get the rank of x in u's preferences
            x_rank = rank[u][x]
            # Get the pair of u
            v = pair_map[u]
            # Get the rank of v in u's preferences
            v_rank = rank[u][v]
            # Check if u prefers x over v
            if x_rank < v_rank:
                unhappy_count += 1
                break

    return unhappy_count

