def minSwaps(grid):
    n = len(grid)
    # Calculate the number of trailing zeros for each row
    trailing_zeros = []
    for row in grid:
        count = 0
        for i in range(n - 1, -1, -1):
            if row[i] == 0:
                count += 1
            else:
                break
        trailing_zeros.append(count)

    swaps = 0
    for i in range(n):
        # The required number of trailing zeros for the i-th row is n - i - 1
        required = n - i - 1
        # Find the first row with at least the required number of trailing zeros
        j = i
        while j < n and trailing_zeros[j] < required:
            j += 1
        if j == n:
            return -1
        # Swap rows to bring the j-th row to the i-th position
        while j > i:
            trailing_zeros[j], trailing_zeros[j - 1] = trailing_zeros[j - 1], trailing_zeros[j]
            swaps += 1
            j -= 1
    return swaps

