    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        required = [n - i - 1 for i in range(n)]
        actual = []
        for row in grid:
            count = 0
            for j in range(n - 1, -1, -1):
                if row[j] == 0:
                    count += 1
                else:
                    break
            actual.append(count)
        swaps = 0
        for i in range(n):
            if actual[i] >= required[i]:
                continue
            found = False
            for j in range(i + 1, n):
                if actual[j] >= required[i]:
                    found = True
                    swaps += j - i
                    actual.insert(i, actual.pop(j))
                    break
            if not found:
                return -1
        return swaps

